from sys import maxsize

def solve(ar):
	dp = [0] * (len(ar) + 1)
	dp[0] = 0
	dp[1] = maxsize
	dp[2] = ar[1] - ar[0]
	for i in range(3, len(ar) + 1):
		dp[i] = min(dp[i - 2] + ar[i - 1] - ar[i - 2], dp[i - 3] + ar[i - 1] - ar[i - 3])
	return dp[len(ar)]

def construct_arr(arr):
	ar = []
	for i in range(len(arr)):
		if arr[i]:
			ar.append(i)
	return ar
for _ in range(int(input())):
	n = int(input())
	ls = list(map(int, input().split()))
	ar = construct_arr(ls)
	if len(ar) == 0:
		print(0)
	elif len(ar) == 1:
		print(-1)
	else:
		ans1 = solve(ar)
		temp1 = ls[-(n - ar[-1]):] + ls[:-(n - ar[-1])]
		temp2 = ls[-(n - ar[-2]):] + ls[:-(n - ar[-2])]
		print(min((solve(ar), solve(construct_arr(temp1)), solve(construct_arr(temp2)))))
